package com.print.kiosk.service.impl;

import com.print.kiosk.dto.request.VerifyCashPaymentRequest;
import com.print.kiosk.dto.response.*;
import com.print.kiosk.entity.*;
import com.print.kiosk.exception.*;
import com.print.kiosk.repository.*;
import com.print.kiosk.service.interfaces.CashPaymentService;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.time.*;
import java.util.*;
import java.util.HexFormat;

@Service
public class CashPaymentServiceImpl implements CashPaymentService{
    private static final ZoneId DHAKA=ZoneId.of("Asia/Dhaka"); private static final SecureRandom RANDOM=new SecureRandom();
    private final PrintRequestRepository requests; private final PrintRequestFileRepository files; private final UserAccountRepository accounts; private final PaymentRecordRepository payments; private final CashPaymentPinRepository pins; private final PrintRequestStatusHistoryRepository history;
    private final byte[] pepper; private final int expiryMinutes,maxAttempts,blockMinutes; private final long deletionHours;
    public CashPaymentServiceImpl(PrintRequestRepository r,PrintRequestFileRepository files,UserAccountRepository a,PaymentRecordRepository p,CashPaymentPinRepository pins,PrintRequestStatusHistoryRepository h,@Value("${app.payment.cash-pin.pepper}")String pepper,@Value("${app.payment.cash-pin.expiry-minutes:5}")int expiry,@Value("${app.payment.cash-pin.max-attempts:5}")int max,@Value("${app.payment.cash-pin.block-minutes:10}")int block,@Value("${app.print-request.file-deletion-delay-hours:24}")long deletionHours){this.requests=r;this.files=files;this.accounts=a;this.payments=p;this.pins=pins;this.history=h;this.pepper=pepper.getBytes(StandardCharsets.UTF_8);this.expiryMinutes=expiry;this.maxAttempts=max;this.blockMinutes=block;this.deletionHours=deletionHours;if(expiry<=0||max<=0||block<=0||pepper.isBlank())throw new IllegalStateException("Cash PIN settings are invalid");}
    @Transactional public CashPinResponse generatePin(Long requestId,Long agentId){UserAccount agent=accounts.findById(agentId).orElseThrow(()->new ResourceNotFoundException("Agent account was not found"));if(agent.getRole()!=AccountRole.AGENT||agent.getAgentStatus()!=AgentStatus.APPROVED)throw new UnauthorizedRequestOperationException("Only an approved agent may generate a cash PIN");PrintRequest r=requests.findByIdForUpdate(requestId).orElseThrow(()->new ResourceNotFoundException("Print request was not found"));if(r.getStatus()!=PrintRequestStatus.AWAITING_PAYMENT||r.getPaymentStatus()!=PaymentStatus.PENDING)throw new InvalidPrintRequestStateException("Only an unpaid request awaiting payment may receive a cash PIN");LocalDateTime now=LocalDateTime.now(DHAKA);if(!r.getExpiresAt().isAfter(now))throw new InvalidPrintRequestStateException("This print request has expired");for(CashPaymentPin old:pins.findActiveByRequestForUpdate(r.getId())){old.setRevokedAt(now);old.getPaymentRecord().setStatus(PaymentStatus.CANCELLED);old.getPaymentRecord().setFailureReason("Replaced by a newly generated PIN");payments.save(old.getPaymentRecord());pins.save(old);}String raw=generateUnique(now);PaymentRecord pr=new PaymentRecord();pr.setPrintRequest(r);pr.setPaymentMethod(PaymentMethod.CASH);pr.setAmount(r.getTotalAmount());pr.setStatus(PaymentStatus.PENDING);pr=payments.save(pr);CashPaymentPin pin=new CashPaymentPin();pin.setPrintRequest(r);pin.setPaymentRecord(pr);pin.setPinHash(hash(raw));pin.setExpiresAt(now.plusMinutes(expiryMinutes));pins.save(pin);return new CashPinResponse(r.getId(),r.getTrackingNumber(),raw,pin.getExpiresAt());}
    @Transactional(noRollbackFor={InvalidPinException.class,ExpiredPinException.class,PinVerificationBlockedException.class,InvalidPrintRequestStateException.class}) public PaymentResponse verifyCash(String tracking,VerifyCashPaymentRequest req){PrintRequest r=requests.findByTrackingNumberForUpdate(tracking.trim().toUpperCase()).orElseThrow(()->new ResourceNotFoundException("Print request was not found or verification failed"));if(!r.getRegistrationNumber().equals(req.getRegistrationNumber().trim()))throw new ResourceNotFoundException("Print request was not found or verification failed");if(r.getStatus()!=PrintRequestStatus.AWAITING_PAYMENT||r.getPaymentStatus()!=PaymentStatus.PENDING)throw new InvalidPrintRequestStateException("This request is not awaiting payment");LocalDateTime now=LocalDateTime.now(DHAKA);if(!r.getExpiresAt().isAfter(now)){PrintRequestStatus previous=r.getStatus();r.setStatus(PrintRequestStatus.EXPIRED);requests.save(r);files.markDeletionEligibleByRequestId(r.getId(),now.plusHours(deletionHours));record(r,previous,PrintRequestStatus.EXPIRED,"Unpaid request expired before payment verification");throw new InvalidPrintRequestStateException("This print request has expired");}List<CashPaymentPin> active=pins.findActiveByRequestForUpdate(r.getId());if(active.isEmpty())throw new ExpiredPinException("No active cash PIN exists for this request");CashPaymentPin pin=active.get(0);if(pin.getBlockedUntil()!=null&&pin.getBlockedUntil().isAfter(now))throw new PinVerificationBlockedException("PIN verification is blocked until "+pin.getBlockedUntil());if(!pin.getExpiresAt().isAfter(now)){pin.setRevokedAt(now);pin.getPaymentRecord().setStatus(PaymentStatus.FAILED);pin.getPaymentRecord().setFailureReason("PIN expired");payments.save(pin.getPaymentRecord());pins.saveAndFlush(pin);throw new ExpiredPinException("Cash PIN has expired");}if(!MessageDigest.isEqual(pin.getPinHash().getBytes(StandardCharsets.UTF_8),hash(req.getPin()).getBytes(StandardCharsets.UTF_8))){int failed=pin.getFailedAttempts()+1;pin.setFailedAttempts(failed);if(failed>=maxAttempts){pin.setBlockedUntil(now.plusMinutes(blockMinutes));pins.saveAndFlush(pin);throw new PinVerificationBlockedException("Too many incorrect attempts. Verification is blocked for "+blockMinutes+" minutes");}pins.saveAndFlush(pin);throw new InvalidPinException("Invalid cash PIN. Remaining attempts: "+(maxAttempts-failed));}pin.setUsedAt(now);PaymentRecord payment=pin.getPaymentRecord();payment.setStatus(PaymentStatus.PAID);payment.setCompletedAt(now);r.setPaymentStatus(PaymentStatus.PAID);PrintRequestStatus previous=r.getStatus();r.setStatus(PrintRequestStatus.PAID);requests.save(r);payments.save(payment);pins.save(pin);record(r,previous,PrintRequestStatus.PAID,"Cash payment verified");return new PaymentResponse(payment.getId(),r.getId(),r.getTrackingNumber(),PaymentMethod.CASH,PaymentStatus.PAID,r.getStatus(),payment.getAmount(),payment.getCompletedAt(),"Payment completed successfully");}
    public List<PaymentOptionResponse> getPaymentOptions(){return List.of(new PaymentOptionResponse(PaymentMethod.CASH,true,"Cash"),new PaymentOptionResponse(PaymentMethod.BKASH,false,"Coming soon"),new PaymentOptionResponse(PaymentMethod.ONE_CARD,false,"Coming soon"));}
    private String generateUnique(LocalDateTime now){for(int i=0;i<20000;i++){String pin=String.format("%04d",RANDOM.nextInt(10000));if(!pins.existsActivePinHash(hash(pin),now))return pin;}throw new IllegalStateException("Unable to generate an available cash PIN");}
    private String hash(String pin){try{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(pepper,"HmacSHA256"));return HexFormat.of().formatHex(mac.doFinal(pin.getBytes(StandardCharsets.UTF_8)));}catch(GeneralSecurityException e){throw new IllegalStateException("Unable to hash cash PIN",e);}}
    private void record(PrintRequest r,PrintRequestStatus old,PrintRequestStatus next,String reason){PrintRequestStatusHistory h=new PrintRequestStatusHistory();h.setPrintRequest(r);h.setPreviousStatus(old);h.setNewStatus(next);h.setActorType(StatusActorType.PUBLIC);h.setReason(reason);history.save(h);}
}